questionvariables.text:
levenshtein(s,t) := block(
  [m,n,prev,curr,i,j,c],
  if stringp(s)=false then s:string(s),
  if stringp(t)=false then t:string(t),
  m:slength(s),
  n:slength(t),
  if m=0 then return(n),
  if n=0 then return(m),
  if m>30 or n>30 then return(100),
  prev:makelist(i,i,0,n),
  for i:1 thru m do (
    curr:[i],
    for j:1 thru n do (
      if charat(s,i)=charat(t,j) then c:0 else c:1,
      curr:endcons(min(prev[j+1]+1,curr[j]+1,prev[j]+c),curr)
    ),
    prev:curr
  ),
  last(prev)
)$ 
lev_score(s, ta) := block(
  [rep, lev, a_plu, rep_ss, d_ss, plu_seul, plu_f1],
  if stringp(s)=false then s:string(s),
  rep: strim(" ", s),
  if slength(rep) # slength(ta) then return(0),
  lev: levenshtein(rep, ta),
  if lev = 0 then return(1),
  a_plu: slength(rep)>1 and charat(rep,slength(rep))="S",
  if a_plu then (
    rep_ss: substring(rep,1,slength(rep)-1),
    d_ss: levenshtein(rep_ss, ta),
    plu_seul: d_ss=0,
    plu_f1: d_ss=1,
    if plu_seul then return(1/2),
    if plu_f1 then return(1/4)
  ),
  if lev = 1 then return(1/2),
  if lev = 2 then return(1/4),
  return(0)
)$ 
cw1_1_ta: "REFLEXION"$ cw1_2_ta: "TIMBRE"$ cw1_3_ta: "TENSION"$ cw1_4_ta: "SON"$ cw1_5_ta: "NIVEAU"$ cw1_6_ta: "DIFFRACTION"$ cw1_7_ta: "LIAISON"$ cw1_8_ta: "AIR"$ cw1_9_ta: "HAUTEUR"$ cw1_10_ta: "ABSORPTION"$ cw1_11_ta: "PERIODE"$ cw1_12_ta: "DUREE"$ cw1_13_ta: "MILIEU"$ cw1_14_ta: "SIGNAL"$ cw1_15_ta: "ONDE"$

