fb_details: ""$ for i:1 thru 15 do (
  rep_disp: if reps[i] = "" then "<i style='color:#94a3b8'>vide</i>" else reps[i],
  if scores[i] = 1 then (
    fb_details: sconcat(fb_details, "<tr><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#64748b;'>", nums[i], ".</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;font-weight:bold;color:#15803d;'>", rep_disp, "</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#15803d;'>✅ 1 pt</td></tr>")
  ) else if scores[i] = 1/2 then (
    fb_details: sconcat(fb_details, "<tr><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#64748b;'>", nums[i], ".</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;font-weight:bold;color:#ca8a04;'>", rep_disp, "</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#ca8a04;'>🔶 0.5 pt (1 faute/pluriel)</td></tr>")
  ) else if scores[i] = 1/4 then (
    fb_details: sconcat(fb_details, "<tr><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#64748b;'>", nums[i], ".</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;font-weight:bold;color:#ea580c;'>", rep_disp, "</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#ea580c;'>🟠 0.25 pt (2 fautes/pluriel+1)</td></tr>")
  ) else (
    fb_details: sconcat(fb_details, "<tr><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#64748b;'>", nums[i], ".</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;font-weight:bold;color:#dc2626;'>", rep_disp, "</td><td style='padding:4px 8px;border-bottom:1px solid #e2e8f0;color:#dc2626;'>❌ 0 pt (Attendu : ", mots[i], ")</td></tr>")
  )
)$ fb_html: sconcat("<div style='margin-top:15px;padding:12px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:8px;'><div style='font-weight:bold;color:#0f766e;margin-bottom:10px;'> Détail par mot :</div><table style='width:100%;border-collapse:collapse;font-size:.85rem;font-family:sans-serif;'>", fb_details, "</table></div>")$
